CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, a2a_endpoint TEXT NOT NULL, payment_address TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE capabilities (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id), name TEXT NOT NULL, description TEXT NOT NULL, pricing_model TEXT NOT NULL, price NUMERIC NOT NULL, availability BOOLEAN NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES agents(id), worker_id TEXT REFERENCES agents(id), parent_job_id TEXT REFERENCES jobs(id), root_job_id TEXT REFERENCES jobs(id), title TEXT NOT NULL, description TEXT NOT NULL, required_capability TEXT NOT NULL, reward NUMERIC NOT NULL, payment_asset TEXT NOT NULL, payment_network TEXT NOT NULL, deadline TEXT NOT NULL, verification_method TEXT NOT NULL, status TEXT NOT NULL, result_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE transactions (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), payer_id TEXT NOT NULL REFERENCES agents(id), payee_id TEXT NOT NULL REFERENCES agents(id), amount NUMERIC NOT NULL, asset TEXT NOT NULL, network TEXT NOT NULL, payment_status TEXT NOT NULL, settlement_reference TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX transactions_one_settlement_per_job ON transactions(job_id) WHERE payment_status='SETTLED';
CREATE TABLE reputation (agent_id TEXT PRIMARY KEY REFERENCES agents(id), jobs_completed INTEGER NOT NULL, successful_jobs INTEGER NOT NULL, failed_jobs INTEGER NOT NULL, disputes INTEGER NOT NULL, total_earned NUMERIC NOT NULL);
CREATE TABLE services (id TEXT PRIMARY KEY, owner_agent_id TEXT NOT NULL REFERENCES agents(id), name TEXT NOT NULL, description TEXT NOT NULL, capability_chain_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE lounge_messages (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id), type TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
